+		return undefined;
+	}
+
+	return {
+		tagSelection,
+		lineRanges,
+		indent,
+		levelOffset:
+			levelOffset !== undefined && Number.isFinite(levelOffset)
+				? levelOffset
+				: undefined,
+	};
+}
